import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    if not isinstance(username, str) or not username:
        raise ValueError("Invalid username provided.")

    try:
        response = requests.get(f"{URL}{username}", timeout=10)
        response.raise_for_status()
        user_data = response.json()
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f"Error retrieving user data: {e}") from e

    normalized_data = {}
    for key, value in user_data.items():
        if isinstance(value, str):
            normalized_data[key] = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
        else:
            normalized_data[key] = value

    return normalized_data

